insert into public.quest_templates (id, source, ability, difficulty, periods, title, flavor, objective, tips, validation, tags, theme, secondary, is_active) values
('for-easy-pompes-20-aujourd-hui', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Pompes, 20 aujourd’hui', 'Les pompes travaillent pectoraux, épaules et triceps sans aucun matériel.', 'Faire 20 pompes dans la journée, en autant de séries que nécessaire (sur les genoux autorisé).', array['Mieux vaut des séries propres que des répétitions bâclées.', 'Découpe en 4 séries de 5 si tu débutes.']::text[], '{"type":"counter","target":20,"unit":"pompes"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-squats-30-aujourd-hui', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Squats, 30 aujourd’hui', 'Les cuisses et les fessiers sont les plus gros muscles du corps : on les sollicite en premier.', 'Faire 30 squats dans la journée, dos droit et talons au sol, en une ou plusieurs séries.', array['Imagine que tu t’assois sur une chaise derrière toi.', 'Descends moins bas si tes genoux tirent.']::text[], '{"type":"counter","target":30,"unit":"squats"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-gainage-3-minutes-au-total', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Gainage, 3 minutes au total', 'Un tronc solide protège le dos et rend tous les autres efforts plus faciles.', 'Tenir la planche pendant 3 minutes en tout dans la journée, en une ou plusieurs séries.', array['Coudes sous les épaules, corps aligné.', 'Fractionne en séries de 20 à 30 secondes si besoin.']::text[], '{"type":"timer","minutes":3}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-fentes-20-aujourd-hui', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Fentes, 20 aujourd’hui', 'Les fentes renforcent chaque jambe séparément et corrigent les déséquilibres.', 'Faire 20 fentes dans la journée (10 par jambe), avant ou arrière.', array['Garde le buste droit et le genou avant au-dessus du pied.', 'Tiens-toi à un mur au début si tu perds l’équilibre.']::text[], '{"type":"counter","target":20,"unit":"fentes"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-chaise-murale-3-tenues', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Chaise murale, 3 tenues', 'Tenir une position statique fatigue les cuisses plus qu’on ne le croit.', 'Tenir la position de la chaise contre un mur 3 fois, aussi longtemps que tu peux (visé : 20 à 30 secondes).', array['Cuisses à l’horizontale, dos plaqué au mur.', 'Repose-toi une minute entre les tenues.']::text[], '{"type":"counter","target":3,"unit":"tenues"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-dips-sur-chaise-15-aujourd-hui', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Dips sur chaise, 15 aujourd’hui', 'Les triceps font la moitié du travail de poussée du haut du corps.', 'Faire 15 dips sur une chaise stable dans la journée, en une ou plusieurs séries.', array['Cale la chaise contre un mur pour qu’elle ne glisse pas.', 'Garde les épaules loin des oreilles.']::text[], '{"type":"counter","target":15,"unit":"dips"}'::jsonb, array['moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-abdominaux-30-aujourd-hui', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Abdominaux, 30 aujourd’hui', 'Les abdominaux stabilisent le tronc dans presque tous les mouvements de force.', 'Faire 30 abdominaux dans la journée (crunchs, relevés de jambes ou ciseaux), en séries courtes.', array['Mains près des tempes, sans tirer sur la nuque.', 'Souffle pendant l’effort.']::text[], '{"type":"counter","target":30,"unit":"abdos"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-portage-de-courses-a-pied', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Portage de courses à pied', 'Porter du poids sollicite tout le corps, comme dans la vraie vie.', 'Porter une charge à la main sur au moins 200 mètres : courses, packs d’eau ou sac chargé de livres.', array['Garde le dos droit et la charge près du corps.', 'Change de main à mi-parcours.']::text[], '{"type":"simple"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-easy-pont-fessier-20-aujourd-hui', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Pont fessier, 20 aujourd’hui', 'Des fessiers forts soulagent le bas du dos et stabilisent le bassin.', 'Faire 20 ponts fessiers dans la journée, en marquant une pause d’une seconde en haut.', array['Pousse avec les talons, pas avec les orteils.', 'Passe sur une jambe quand c’est facile.']::text[], '{"type":"counter","target":20,"unit":"ponts"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-escaliers-a-pied-3-etages', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Escaliers à pied, 3 étages', 'Monter à pied est un effort de force et de souffle gratuit, que tu croises chaque jour.', 'Monter 3 étages à pied dans la journée, au total, plutôt que de prendre l’ascenseur.', array['Pose le pied entier sur la marche.', 'Monte une marche sur deux si tu te sens à l’aise.']::text[], '{"type":"counter","target":3,"unit":"étages"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-circuit-express-4-exercices', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Circuit express, 4 exercices', 'Un circuit court sollicite tous les groupes musculaires en peu de temps.', 'Enchaîner 4 exercices l’un après l’autre : 10 pompes, 15 squats, 20 fentes (10 par jambe), 30 secondes de gainage.', array['Repose-toi à ton rythme entre les exercices.', 'Coche chaque exercice au fur et à mesure.']::text[], '{"type":"steps","steps":["10 pompes","15 squats","20 fentes","30 secondes de gainage"]}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-souleves-de-charge-15', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Soulevés de charge, 15', 'Savoir soulever correctement protège le dos pour tous les jours qui viennent.', 'Faire 15 soulevés de charge (sac lesté, bidon d’eau) en gardant le dos droit.', array['Fléchis les genoux, ne plie pas le dos.', 'Garde la charge collée contre toi.']::text[], '{"type":"counter","target":15,"unit":"soulevés"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-easy-tirages-et-rowing-20', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Tirages et rowing, 20', 'Le dos fait contrepoids à tout ce qu’on pousse : il se travaille aussi.', 'Faire 20 tirages dans la journée avec un élastique, un sac chargé ou une table solide.', array['Tire les coudes vers l’arrière, pas les épaules vers les oreilles.', 'Contrôle la descente.']::text[], '{"type":"counter","target":20,"unit":"tirages"}'::jsonb, array['moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-burpees-10-aujourd-hui', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Burpees, 10 aujourd’hui', 'Le burpee réveille tout le corps en un seul mouvement.', 'Faire 10 burpees dans la journée, en séries de 3 à 5 si besoin.', array['Supprime le saut ou la pompe si c’est trop dur.', 'Garde un rythme régulier plutôt que de te presser.']::text[], '{"type":"counter","target":10,"unit":"burpees"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-pompes-40-aujourd-hui', 'catalog', 'FOR', 'medium', array['daily']::text[], 'Pompes, 40 aujourd’hui', 'Doubler la dose du jour fait franchir un cap sans mettre en danger les épaules.', 'Faire 40 pompes dans la journée, en autant de séries que nécessaire.', array['Fais 4 séries de 10 réparties dans la journée.', 'Note ton total pour battre ton record demain.']::text[], '{"type":"counter","target":40,"unit":"pompes"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-squats-60-aujourd-hui', 'catalog', 'FOR', 'medium', array['daily']::text[], 'Squats, 60 aujourd’hui', 'Un volume de squats régulier construit des jambes solides pour la vie.', 'Faire 60 squats dans la journée, en séries de 15 à 20 avec du repos entre.', array['Descends en contrôle, remonte avec force.', 'Garde les genoux dans l’axe des pieds.']::text[], '{"type":"counter","target":60,"unit":"squats"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-pompes-200-dans-la-semaine', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Pompes, 200 dans la semaine', 'Quelques séries par jour s’additionnent vite : 200 pompes, c’est 30 par jour.', 'Cumuler 200 pompes sur la semaine, en autant de séries et de jours que tu veux.', array['Fais 30 pompes par jour pendant 7 jours.', 'Ajoute tes pompes après chaque série.']::text[], '{"type":"counter","target":200,"unit":"pompes"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-seance-au-poids-du-corps', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Séance au poids du corps', 'Une séance structurée progresse plus vite que des séries lancées au hasard.', 'Faire une séance complète : échauffement, 3 séries de 10 pompes, 3 séries de 15 squats et 3 gainages de 30 secondes.', array['Repos de 45 à 60 secondes entre les séries.', 'Coche chaque bloc au fur et à mesure.']::text[], '{"type":"steps","steps":["Échauffement","3 séries de 10 pompes","3 séries de 15 squats","3 gainages de 30 secondes"]}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-squats-300-dans-la-semaine', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Squats, 300 dans la semaine', 'Le bas du corps se construit au volume, jour après jour.', 'Cumuler 300 squats sur la semaine, répartis comme tu veux.', array['Une série de 50 par jour suffit largement.', 'Passe aux squats lestés quand ça devient facile.']::text[], '{"type":"counter","target":300,"unit":"squats"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-gainage-5-minutes-au-total', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Gainage, 5 minutes au total', 'Cinq minutes de planche, c’est un vrai travail du tronc, loin de la routine.', 'Tenir des planches (face et côtés) pendant 5 minutes en tout, en plusieurs séries.', array['Garde le corps aligné, sans cambrer.', 'Repose-toi dès que la forme se dégrade.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-abdominaux-200-dans-la-semaine', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Abdominaux, 200 dans la semaine', 'Un tronc solide protège le dos dans tous les efforts.', 'Cumuler 200 abdominaux (crunchs, relevés de jambes, ciseaux) sur la semaine.', array['Fais 30 par jour en deux séries.', 'Varie les exercices pour ne pas t’ennuyer.']::text[], '{"type":"counter","target":200,"unit":"abdos"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-pompes-et-dips-30-de-chaque', 'catalog', 'FOR', 'medium', array['daily']::text[], 'Pompes et dips, 30 de chaque', 'Pousser sur deux plans différents travaille mieux les épaules et les triceps.', 'Faire 30 pompes et 30 dips dans la journée, en séries libres.', array['Alterne pompes et dips pour reposer chaque groupe.', 'Cale bien la chaise des dips contre un mur.']::text[], '{"type":"counter","target":60,"unit":"répétitions"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-seances-de-force-3-dans-la-semaine', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Séances de force, 3 dans la semaine', 'Trois séances de force par semaine suffisent à progresser régulièrement.', 'Faire 3 séances de renforcement musculaire sur la semaine, de n’importe quelle durée, avec au moins un jour de repos entre.', array['Répartis par exemple lundi, mercredi, vendredi.', 'Pas besoin de matériel : le poids du corps suffit.']::text[], '{"type":"counter","target":3,"unit":"séances"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-tirages-30-repetitions', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Tirages, 30 répétitions', 'Tractions, rowing et élastiques équilibrent la poussée et protègent les épaules.', 'Faire 30 tirages (tractions, rowing, élastique) en séries de 6 à 12.', array['Une barre de porte ou une table solide suffit.', 'Aide-toi d’un élastique pour les tractions.']::text[], '{"type":"counter","target":30,"unit":"tirages"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-fentes-150-dans-la-semaine', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Fentes, 150 dans la semaine', 'Les fentes bâtissent des jambes stables et corrigent les déséquilibres entre droite et gauche.', 'Cumuler 150 fentes (avant ou arrière) sur la semaine.', array['Environ 25 fentes par jour, en alternant les jambes.', 'Garde le buste droit.']::text[], '{"type":"counter","target":150,"unit":"fentes"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-circuit-de-3-tours', 'catalog', 'FOR', 'medium', array['daily']::text[], 'Circuit de 3 tours', 'Un circuit répété installe la force et l’endurance musculaire à la fois.', 'Faire 3 tours d’un circuit : 10 pompes, 15 squats, 10 fentes par jambe et 20 secondes de gainage.', array['Repose-toi 1 minute entre les tours.', 'Garde la même qualité de mouvement du premier au dernier tour.']::text[], '{"type":"steps","steps":["Tour 1","Tour 2","Tour 3"]}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-high-pompes-400-dans-la-semaine', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Pompes, 400 dans la semaine', 'Quatre cents pompes dans la semaine font franchir un palier visible.', 'Cumuler 400 pompes sur la semaine, soit environ 60 par jour.', array['Prévois 3 séries par jour.', 'Garde un jour plus léger pour récupérer.']::text[], '{"type":"counter","target":400,"unit":"pompes"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-high-seances-de-force-4-dans-la-semaine', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Séances de force, 4 dans la semaine', 'Quatre séances de force par semaine installent un vrai rythme d’entraînement.', 'Faire 4 séances de renforcement ou de musculation sur la semaine, en gardant au moins un jour de repos complet.', array['Alterne haut et bas du corps.', 'Note chaque séance dans un carnet.']::text[], '{"type":"counter","target":4,"unit":"séances"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-high-pompes-80-en-series', 'catalog', 'FOR', 'high', array['daily', 'weekly']::text[], 'Pompes, 80 en séries', 'Un gros volume de pompes en une fois demande de la gestion d’effort.', 'Faire 80 pompes en séries de ton choix, avec repos libre entre les séries.', array['Fais des séries de 10 à 15 pour garder de la qualité.', 'Passe sur les genoux dès que la forme se dégrade.']::text[], '{"type":"counter","target":80,"unit":"pompes"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-high-squats-500-dans-la-semaine', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Squats, 500 dans la semaine', 'Cinq cents squats dans la semaine, c’est l’équivalent de quelques séries par jour.', 'Cumuler 500 squats sur la semaine, avec ou sans charge.', array['Environ 70 par jour en 3 séries.', 'Ajoute du poids quand c’est facile.']::text[], '{"type":"counter","target":500,"unit":"squats"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-high-gainage-15-minutes-cumulees', 'catalog', 'FOR', 'high', array['weekly', 'monthly']::text[], 'Gainage, 15 minutes cumulées', 'Un gainage long et régulier sculpte un tronc stable et résistant.', 'Cumuler 15 minutes de gainage sur la période, en séries de 30 secondes à 2 minutes.', array['Note chaque série pour suivre ton total.', 'Varie face, côtés et dos.']::text[], '{"type":"counter","target":15,"unit":"minutes"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-high-portage-lourd-5-sorties', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Portage lourd, 5 sorties', 'Travailler la force fonctionnelle, c’est porter lourd, sur une vraie distance.', 'Faire 5 portages de charge lourde dans la semaine : sacs, packs, bidons ou valises, sur au moins 200 mètres chacun.', array['Charge à 60 % de ce que tu peux porter.', 'Repose-toi dès que ton dos s’arrondit.']::text[], '{"type":"counter","target":5,"unit":"portages"}'::jsonb, array['extérieur', 'sport']::text[], null, '[]'::jsonb, true),
('for-high-pompes-1-000-dans-le-mois', 'catalog', 'FOR', 'high', array['monthly']::text[], 'Pompes, 1 000 dans le mois', 'Mille pompes en un mois, c’est environ 35 par jour : un défi classique, et très accessible.', 'Cumuler 1 000 pompes sur le mois, en autant de séries que nécessaire.', array['Planifie 35 pompes par jour, ou 50 un jour sur deux.', 'Ajoute tes pompes après chaque série.']::text[], '{"type":"counter","target":1000,"unit":"pompes"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-high-seances-de-force-12-dans-le-mois', 'catalog', 'FOR', 'high', array['monthly']::text[], 'Séances de force, 12 dans le mois', 'Douze séances par mois, c’est trois par semaine : un rythme durable.', 'Faire 12 séances de renforcement musculaire sur le mois.', array['Planifie trois créneaux fixes par semaine.', 'Alterne séances courtes et longues.']::text[], '{"type":"counter","target":12,"unit":"séances"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-high-tirages-150-dans-le-mois', 'catalog', 'FOR', 'high', array['monthly']::text[], 'Tirages, 150 dans le mois', 'Un bon équilibre entre pousser et tirer protège les épaules.', 'Cumuler 150 tirages (tractions, rowing, élastique) sur le mois.', array['Environ 5 par jour, ou 15 trois fois par semaine.', 'Contrôle la descente à chaque répétition.']::text[], '{"type":"counter","target":150,"unit":"tirages"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-expert-pompes-2-000-dans-le-mois', 'catalog', 'FOR', 'expert', array['monthly']::text[], 'Pompes, 2 000 dans le mois', 'Deux mille pompes en un mois : un vrai défi de constance.', 'Cumuler 2 000 pompes sur le mois, soit environ 70 par jour. Adapte à ta condition et consulte un professionnel au besoin.', array['Fais 3 à 4 séries réparties dans la journée.', 'Garde au moins un jour de repos par semaine.']::text[], '{"type":"counter","target":2000,"unit":"pompes"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-expert-record-de-pompes-a-battre', 'catalog', 'FOR', 'expert', array['monthly', 'epic']::text[], 'Record de pompes à battre', 'Mesurer, s’entraîner, puis mesurer encore : la forme la plus honnête de progression.', 'Mesurer ton maximum de pompes d’affilée, t’entraîner 4 semaines, puis refaire le test et améliorer ton record. Adapte à ta condition.', array['Note ton record de départ sur papier.', 'Entraîne-toi 3 fois par semaine avec des séries sous ton maximum.']::text[], '{"type":"steps","steps":["Mesurer mon maximum de pompes d’affilée","S’entraîner pendant 4 semaines","Refaire le test et battre mon record"]}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-expert-seances-de-force-20-au-total', 'catalog', 'FOR', 'expert', array['weekly', 'monthly']::text[], 'Séances de force, 20 au total', 'Vingt séances de force cumulées demandent de la discipline sur la durée.', 'Faire 20 séances de renforcement musculaire sur la période. Adapte à ta condition et à ton niveau de récupération.', array['Prévois des créneaux fixes dans ton agenda.', 'Alterne les groupes musculaires.']::text[], '{"type":"counter","target":20,"unit":"séances"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-expert-squats-5-000-au-total', 'catalog', 'FOR', 'expert', array['monthly', 'epic']::text[], 'Squats, 5 000 au total', 'Cinq mille squats : un grand cycle de jambes, du premier jour au dernier.', 'Cumuler 5 000 squats, avec ou sans charge, sur la durée. Adapte à ta condition et consulte un professionnel au besoin.', array['Environ 150 par jour pendant un peu plus d’un mois.', 'Ajoute du poids progressivement.']::text[], '{"type":"counter","target":5000,"unit":"squats"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-expert-force-16-seances-dans-le-mois', 'catalog', 'FOR', 'expert', array['monthly']::text[], 'Force, 16 séances dans le mois', 'Seize séances de force dans le mois, c’est quatre par semaine sans exception.', 'Faire 16 séances de renforcement musculaire sur le mois. Adapte à ta condition et garde deux jours de repos par semaine.', array['Planifie tes séances dans ton agenda.', 'Alterne séances lourdes et séances légères.']::text[], '{"type":"counter","target":16,"unit":"séances"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-easy-etirements-complets-6-zones', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Étirements complets, 6 zones', 'Un corps souple se blesse moins et bouge avec plus d’aisance.', 'Étirer successivement nuque, épaules, dos, hanches, cuisses et mollets, 30 secondes par zone.', array['Respire lentement dans chaque position.', 'Ne force jamais jusqu’à la douleur.']::text[], '{"type":"counter","target":6,"unit":"zones"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('dex-easy-equilibre-sur-une-jambe-4-tenues', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Équilibre sur une jambe, 4 tenues', 'L’équilibre se travaille comme un muscle et protège contre les chutes.', 'Tenir en équilibre sur une jambe 4 fois (2 par jambe), 30 secondes chacune, yeux ouverts.', array['Fixe un point devant toi.', 'Garde un mur à portée de main au début.']::text[], '{"type":"counter","target":4,"unit":"tenues"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('dex-easy-jonglage-5-tentatives', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Jonglage, 5 tentatives', 'Le jonglage entraîne la coordination œil-main et la concentration.', 'Tenter 5 fois une cascade de trois balles (ou foulards, ou chaussettes roulées), même si elle ne tient que quelques lancers.', array['Commence avec deux balles.', 'Lance à hauteur des yeux, regarde le sommet de la trajectoire.']::text[], '{"type":"counter","target":5,"unit":"tentatives"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], null, '[]'::jsonb, true),
('dex-easy-mobilite-epaules-et-hanches', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Mobilité épaules et hanches', 'Ces deux articulations limitent beaucoup de gestes : elles méritent un travail régulier.', 'Faire 10 rotations lentes et amples de chaque épaule et de chaque hanche.', array['Bouge lentement, sans à-coups.', 'Respire normalement.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
