('dex-medium-equilibre-yeux-fermes-6-tenues', 'catalog', 'DEX', 'medium', array['daily']::text[], 'Équilibre yeux fermés, 6 tenues', 'Travailler l’équilibre sollicite les petits muscles stabilisateurs des chevilles et des genoux.', 'Tenir en équilibre sur une jambe 6 fois (3 par jambe) : 3 yeux ouverts, 3 yeux fermés, 30 secondes chacune.', array['Garde un mur à portée de main.', 'Ferme les yeux seulement quand tu es stable.']::text[], '{"type":"counter","target":6,"unit":"tenues"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
