('dex-medium-geste-precis-4-seances', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'Geste précis, 4 séances', 'La pratique régulière d’un geste précis (instrument, dessin, couture, modélisme) affine la dextérité manuelle.', 'Pratiquer 4 fois dans la semaine un geste précis : instrument, dessin, couture, calligraphie, modélisme.', array['Répartis sur 4 jours.', 'Ne cherche pas la perfection, cherche la régularité.']::text[], '{"type":"counter","target":4,"unit":"séances"}'::jsonb, array['sans matériel']::text[], null, '[]'::jsonb, true),
