('dex-expert-geste-maitrise-un-vrai-projet', 'catalog', 'DEX', 'expert', array['monthly', 'epic']::text[], 'Geste maîtrisé, un vrai projet', 'Maîtriser un geste précis passe par un vrai projet, avec un résultat à montrer.', 'Mener un projet de pratique d’un geste manuel précis (instrument, dessin, couture, calligraphie) jusqu’à un résultat présentable.', array['Choisis un objectif concret.', 'Garde des traces de ta progression.']::text[], '{"type":"steps","steps":["Choisir un geste et un objectif","Pratiquer au moins 20 séances","Présenter le résultat à quelqu’un"]}'::jsonb, array['sans matériel']::text[], null, '[]'::jsonb, true),
