('con-easy-marche-15-minutes', 'catalog', 'CON', 'easy', array['daily']::text[], 'Marche, 15 minutes', 'Marcher un quart d’heure par jour est le geste de santé le plus simple et le plus efficace.', 'Marcher 15 minutes, dehors si possible, à un rythme soutenu, d’une traite ou en plusieurs fois.', array['Un peu d’air, sans écran.', 'Tu peux les répartir en deux sorties de 8 minutes.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['extérieur', 'sport']::text[], null, '[]'::jsonb, true),
