('g-danse-zumba-t3', 'catalog', 'DEX', 'high', array['monthly']::text[], 'Zumba, 6 heures ce mois-ci', 'La zumba mêle danse et cardio : on bouge sans penser à l’effort. Un mois de pratique régulière installe l’habitude et le niveau.', 'Cumuler 6 heures sur le mois : suivre un cours de zumba (chorégraphies rythmées et cardio), avec un cours ou un programme guidé.', array['Suis le rythme avant de chercher l’exactitude des pas.', 'Planifie tes créneaux à l’avance et note ta progression chaque semaine.']::text[], '{"type":"counter","target":360,"unit":"minutes"}'::jsonb, array['guidé', 'danse', 'sport']::text[], 'danse', '[{"ability":"CHA","pct":30},{"ability":"FOR","pct":10}]'::jsonb, true),
('g-danse-zumba-t4', 'catalog', 'DEX', 'expert', array['epic']::text[], 'Zumba, 25 heures de pratique', 'La zumba mêle danse et cardio : on bouge sans penser à l’effort. Un grand objectif, qui demande de la constance sur la durée.', 'Cumuler 25 heures de pratique guidée (suivre un cours de zumba (chorégraphies rythmées et cardio)) jusqu’à suivre un cours complet de 45 minutes sans pause. Adapte à ta condition et consulte un professionnel au besoin.', array['Suis le rythme avant de chercher l’exactitude des pas.', 'Fixe-toi un point d’étape toutes les deux semaines pour mesurer ta progression.']::text[], '{"type":"counter","target":1500,"unit":"minutes"}'::jsonb, array['guidé', 'danse', 'sport']::text[], 'danse', '[{"ability":"CHA","pct":30},{"ability":"FOR","pct":10}]'::jsonb, true),
('g-musculation-muscu-haut-du-corps-t1', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Muscu haut du corps, 30 minutes guidées', 'Un haut du corps solide facilite pousser, tirer et porter.', 'Pendant 30 minutes, faire une séance de musculation du haut du corps (pectoraux, épaules, bras), en suivant un cours guidé (vidéo, application ou professeur).', array['Déroulé conseillé : échauffement des épaules, 4 exercices en 3 séries, étirements.', 'Garde les omoplates serrées et contrôle chaque descente.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['guidé', 'musculation', 'sport']::text[], 'musculation', '[{"ability":"CON","pct":20}]'::jsonb, true),
