('g-botanique-plantes-d-interieur-t1', 'catalog', 'INT', 'easy', array['daily']::text[], 'Plantes d’intérieur, 25 minutes guidées', 'Les plantes d’intérieur apportent calme et air plus sain.', 'Pendant 25 minutes, entretenir tes plantes d’intérieur (arrosage, lumière, rempotage), en suivant un cours guidé (vidéo, application ou professeur).', array['Déroulé conseillé : observer chaque plante, arroser selon ses besoins, nettoyer les feuilles, rempoter si besoin.', 'Arrose quand la terre est sèche sur 2 cm, pas selon un calendrier.']::text[], '{"type":"timer","minutes":25}'::jsonb, array['guidé', 'botanique']::text[], 'botanique', '[{"ability":"SAG","pct":30},{"ability":"CON","pct":20}]'::jsonb, true),
